ate / frequency;    // \u77e9\u5f62\u6ce2\u306e\u534a\u6ce2\u9577\n\nint count = 0;\nint i2s_read = 0;\nbool i2s_test = true;\n\nvoid setup() {\n  Serial.begin(115200);\n  while(!Serial);             // \u30b7\u30ea\u30a2\u30eb\u30dd\u30fc\u30c8\u304c\u63a5\u7d9a\u3055\u308c\u308b\u307e\u3067\u5f85\u6a5f\n\n  I2S.setPins(8, 7, 43, 44);  // I2S \u30d4\u30f3\u3092\u8a2d\u5b9a\n  if (!I2S.begin(I2S_MODE_STD, sampleRate, I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO)){\n    Serial.println("I2S \u306e\u521d\u671f\u5316\u306b\u5931\u6557\u3057\u307e\u3057\u305f\uff01");\n    while(1);                 // \u521d\u671f\u5316\u306b\u5931\u6557\u3057\u305f\u5834\u5408\u306f\u505c\u6b62\n  }\n}\n\nvoid loop() {\n  if(i2s_test){\n    Serial.println("I2S \u30c6\u30b9\u30c8\u958b\u59cb\uff01");\n\n    // \u77e9\u5f62\u6ce2\u30b5\u30f3\u30d7\u30eb\u3092\u751f\u6210\u3057\u3066\u66f8\u304d\u8fbc\u307f\n    for(int i = 0; i < 32000; i++){\n      if(count % halfWavelength == 0){\n        sample = -sample;    // \u30b5\u30f3\u30d7\u30eb\u5024\u3092\u5207\u308a\u66ff\u3048\u3066\u77e9\u5f62\u6ce2\u3092\u751f\u6210\n      }\n      I2S.write(sample);     // \u53f3\u30c1\u30e3\u30f3\u30cd\u30eb\u306b\u30b5\u30f3\u30d7\u30eb\u3092\u66f8\u304d\u8fbc\u307f\n      count++;\n    }\n\n    // I2S \u304b\u3089\u30b5\u30f3\u30d7\u30eb\u3092\u8aad\u307f\u53d6\u308a\u3001\u975e\u30bc\u30ed\u30b5\u30f3\u30d7\u30eb\u3092\u30ab\u30a6\u30f3\u30c8\n    i2s_read=0;\n    for(int i = 0; i < 32000; i++){\n      int sample_read = I2S.read();\n      Serial.print(sample_read);\n      Serial.print(" ");\n      if(sample_read != 0 && sample_read != 0xFFFF){\n        i2s_read++;\n      }\n    }\n    Serial.println();\n\n    // \u6709\u52b9\u306a\u30b5\u30f3\u30d7\u30eb\u6570\u304c\u95be\u5024\u3092\u8d85\u3048\u3066\u3044\u308b\u304b\u78ba\u8a8d\n    if(i2s_read > 16000){\n      Serial.println("I2S RX \u5408\u683c\uff01");\n    } else{\n      i2s_read = 0;\n      for(int i = 0; i < 32000; i++){\n        int sample_read = I2S.read();\n        if (sample_read != 0 && sample_read != 0xFFFF){\n          i2s_read++;\n        }\n      }\n      if(i2s_read > 16000)\n        Serial.println("I2S RX \u5408\u683c\uff01");\n      else\n        Serial.println("I2S RX \u4e0d\u5408\u683c\uff01");\n    }\n\n    Serial.println("\u7d42\u4e86");\n    i2s_test = false;\n  }\n}\n')),(0,i.yg)("p",null,"\u53d7\u4fe1\u3057\u305f\u975e\u30bc\u30ed\u30b5\u30f3\u30d7\u30eb\u306e\u6570\u304c\u95be\u5024\uff08\u3053\u306e\u5834\u5408\u306f 16000\uff09\u3092\u8d85\u3048\u305f\u5834\u5408\u3001I2S \u306e\u53d7\u4fe1\u306f\u5408\u683c\u3068\u307f\u306a\u3055\u308c\u307e\u3059\u3002\u305d\u308c\u4ee5\u5916\u306e\u5834\u5408\u306f\u4e0d\u5408\u683c\u3068\u307f\u306a\u3055\u308c\u307e\u3059\u3002"),(0,i.yg)("p",null,"\u30c6\u30b9\u30c8\u7d50\u679c\uff08I2S \u30b5\u30f3\u30d7\u30eb\u5024\u3068\u5408\u683c/\u4e0d\u5408\u683c\u306e\u30b9\u30c6\u30fc\u30bf\u30b9\u3092\u542b\u3080\uff09\u306f\u3001\u30b7\u30ea\u30a2\u30eb\u30e2\u30cb\u30bf\u30fc\u306b\u51fa\u529b\u3055\u308c\u307e\u3059\u3002"),(0,i.yg)("p",null,(0,i.yg)("inlineCode",{parentName:"p"},"Serial Monitor")," \u3092\u958b\u3044\u3066\u30c6\u30b9\u30c8\u7d50\u679c\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002"),(0,i.yg)("p",{style:{textAlign:"center"}},(0,i.yg)("img",{src:"https://files.seeedstudio.com/wiki/SenseCAP/respeaker/i2s-test-pass.png",alt:"pir",width:800,height:"auto"})))}u.isMDXComponent=!0}}]);